def dataset():
    notes = {"root.md": "\n".join("[["+domain+"]]" for domain in dict.fromkeys(t[0] for t in TOPICS))}
    cases = []
    for index, (domain, split, title, en, ru, implicit, implicit_ru) in enumerate(TOPICS):
        target = "Branches/"+title+".md"
        parent = "Branches/"+domain+".md"
        notes.setdefault(parent, "#main\n")
        notes[parent] += "[["+title+"]]\n"
        notes[target] = "#key\n"+title+"\n[[Evidence "+str(index)+"]]"
        notes["Notes/Evidence "+str(index)+".md"] = en+"\n"+ru+"\n[["+title+"]]"
        samples = [implicit, implicit_ru, title+". "+implicit, title+". "+implicit_ru,
                   "Research on "+title+": "+implicit,
                   "Исследование "+title+": "+implicit_ru,
                   "Research question: "+implicit+"\nSubject area: "+title,
                   "Подробное описание темы "+title+"\n"+("This document discusses the source and its explanation. "*40)+implicit_ru]
        for variant, source in enumerate(samples):
            # A source may overlap facts, but it is never itself an indexed note/profile member.
            cases.append({"id": f"{index:02d}-{variant}", "group": domain, "split": split,
                "source": source, "acceptable": [target], "must_pool": False,
                "reason": "The material concerns the named discipline; its evidence note links to this unique root-reachable key."})
        others = [t for t in TOPICS if t[1] == split and t[0] != domain]
        other = others[index % len(others)]
        mixed = en+"\nIndependently, "+other[3]
        cases.append({"id": f"{index:02d}-mixed", "group": domain, "split": split,
            "source": mixed, "acceptable": [], "must_pool": True,
            "reason": "Two unrelated disciplines have equal source evidence; no single branch is justified."})
        unrelated = ["ceramic glazing recipes", "medieval musical notation", "basket weaving traditions"][["development", "calibration", "test"].index(split)]
        cases.append({"id": f"{index:02d}-new", "group": domain, "split": split,
            "source": f"Unindexed research record {index}: {unrelated}. No statement about {title} is provided.",
            "acceptable": [], "must_pool": True, "reason": "The source explicitly lacks evidence about the tempting title; the actual topic is absent."})
    return {"schema": "context-indexing.corpus.v1", "origin": "authored synthetic bilingual engineering fixtures",
            "notes": notes, "cases": cases}
